DROP TABLE IF EXISTS `audit_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `audit_logs` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `transactionId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `transactionType` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `loanId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customerId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `userId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `action` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `previousStatus` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `newStatus` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `previousBalance` text COLLATE utf8mb4_unicode_ci,
  `newBalance` text COLLATE utf8mb4_unicode_ci,
  `amount` decimal(18,2) DEFAULT '0.00',
  `currency` varchar(3) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `makerUserId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `checkerUserId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `headApproverUserId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `adminUserId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reason` text COLLATE utf8mb4_unicode_ci,
  `referenceTransactionId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `relatedTransactionId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sourceRequestId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ip` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `userAgent` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  KEY `IDX_cee5459245f652b75eb2759b4c` (`action`),
  KEY `IDX_bea7d6f5c76f9281eec0252ca2` (`customerId`),
  KEY `IDX_1f84fa70454d7953b670c8cc33` (`loanId`),
  KEY `IDX_be80872dfaac5478a829d1c764` (`transactionId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
