--
-- Table structure for table `kyc_documents`
--

DROP TABLE IF EXISTS `kyc_documents`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `kyc_documents` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `customerId` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `documentType` enum('NATIONAL_ID','ID_CARD','PASSPORT','FAMILY_BOOK','SELFIE_WITH_ID','SIGNATURE') COLLATE utf8mb4_unicode_ci NOT NULL,
  `variant` enum('MAIN','FRONT','BACK') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MAIN',
  `fileName` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mimeType` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sizeBytes` int NOT NULL,
  `checksum` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `issuedAt` date DEFAULT NULL,
  `expiresAt` date DEFAULT NULL,
  `note` text COLLATE utf8mb4_unicode_ci,
  `uploadedBy` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  KEY `IDX_d8b3c70c462ed79de3b4227e67` (`customerId`,`documentType`),
  KEY `IDX_7d56b4deb5797ba5c475ceef56` (`customerId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

