--
-- Table structure for table `payment_requests`
--

DROP TABLE IF EXISTS `payment_requests`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payment_requests` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `requestNo` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `loanId` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `customerId` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `cashAmount` decimal(18,2) NOT NULL DEFAULT '0.00',
  `creditApplied` decimal(18,2) NOT NULL DEFAULT '0.00',
  `currency` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'LAK',
  `status` enum('PENDING','APPROVED','REJECTED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `previousRequestId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `settlementAgreementId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `note` text COLLATE utf8mb4_unicode_ci,
  `rejectionReason` text COLLATE utf8mb4_unicode_ci,
  `createdBy` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `approvedBy` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `rejectedBy` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `approvedAt` datetime DEFAULT NULL,
  `rejectedAt` datetime DEFAULT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `IDX_c04e7188273f7c74db8e477fc6` (`requestNo`),
  KEY `IDX_9186583d5d17a8d66ab310edb7` (`previousRequestId`),
  KEY `IDX_0665f7e5373eb19a15ddd57a31` (`status`),
  KEY `IDX_9dc12721cd231f9267c9dbe1a9` (`loanId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

